[metadata] {"type": "create", "filePath": "/root/.agent/diagrams/water-stress-dashboard.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Global Water Stress: Multi-Indicator Country Comparison</title>
  <link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@300;400;500;600;700&family=IBM+Plex+Mono:wght@400;500&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg: #0d1117;
      --surface-0: #0d1117;
      --surface-1: #161b22;
      --surface-2: #21262d;
      --surface-3: #30363d;
      --border: rgba(240,246,252,0.1);
      --border-strong: rgba(240,246,252,0.2);
      --text: #e6edf3;
      --text-dim: #8b949e;
      --text-muted: #6e7681;

      /* Water stress severity palette */
      --critical: #da3633;       /* Extremely High */
      --critical-dim: rgba(218,54,51,0.15);
      --high: #e3882a;           /* High */
      --high-dim: rgba(227,136,42,0.15);
      --medium-high: #d4a73a;    /* Medium-High */
      --medium-high-dim: rgba(212,167,58,0.15);
      --medium: #5ca9e8;         /* Medium */
      --medium-dim: rgba(92,169,232,0.15);
      --low: #3fb950;            /* Low */
      --low-dim: rgba(63,185,80,0.15);

      --accent-teal: #0891b2;
      --accent-slate: #0369a1;

      --font-body: 'IBM Plex Sans', -apple-system, sans-serif;
      --font-mono: 'IBM Plex Mono', 'Courier New', monospace;
    }

    * { box-sizing: border-box; margin: 0; padding: 0; }

    body {
      background: var(--bg);
      color: var(--text);
      font-family: var(--font-body);
      font-size: 13px;
      line-height: 1.5;
      min-height: 100vh;
      background-image:
        radial-gradient(ellipse 80% 40% at 20% -10%, rgba(8,145,178,0.06) 0%, transparent 60%),
        radial-gradient(ellipse 60% 30% at 80% 110%, rgba(218,54,51,0.05) 0%, transparent 60%);
    }

    .page {
      max-width: 1400px;
      margin: 0 auto;
      padding: 32px 24px 48px;
    }

    /* ── HEADER ── */
    header {
      border-bottom: 1px solid var(--border);
      padding-bottom: 20px;
      margin-bottom: 28px;
    }

    .header-top {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 16px;
      flex-wrap: wrap;
    }

    .label-tag {
      font-family: var(--font-mono);
      font-size: 10px;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--accent-teal);
      background: rgba(8,145,178,0.1);
      border: 1px solid rgba(8,145,178,0.3);
      padding: 2px 8px;
      border-radius: 2px;
      display: inline-block;
      margin-bottom: 8px;
    }

    h1 {
      font-size: 22px;
      font-weight: 600;
      line-height: 1.3;
      color: var(--text);
      letter-spacing: -0.3px;
    }

    .subtitle {
      color: var(--text-dim);
      font-size: 13px;
      margin-top: 4px;
    }

    .meta-pills {
      display: flex;
      gap: 8px;
      flex-wrap: wrap;
      align-items: center;
    }

    .meta-pill {
      font-family: var(--font-mono);
      font-size: 10px;
      color: var(--text-muted);
      background: var(--surface-2);
      border: 1px solid var(--border);
      padding: 3px 8px;
      border-radius: 2px;
    }

    /* ── STRESS LEGEND ── */
    .legend-strip {
      display: flex;
      gap: 16px;
      flex-wrap: wrap;
      margin-bottom: 24px;
      padding: 12px 16px;
      background: var(--surface-1);
      border: 1px solid var(--border);
      border-radius: 4px;
      align-items: center;
    }

    .legend-title {
      font-family: var(--font-mono);
      font-size: 10px;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--text-muted);
      margin-right: 4px;
    }

    .legend-item {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 11px;
      color: var(--text-dim);
    }

    .legend-dot {
      width: 10px;
      height: 10px;
      border-radius: 50%;
      flex-shrink: 0;
    }

    /* ── MAIN GRID ── */
    .main-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      grid-template-rows: auto auto;
      gap: 20px;
    }

    .chart-card {
      background: var(--surface-1);
      border: 1px solid var(--border);
      border-radius: 6px;
      padding: 20px;
      position: relative;
      overflow: hidden;
    }

    .chart-card::before {
      content: '';
      position: absolute;
      top: 0; left: 0; right: 0;
      height: 2px;
    }

    .chart-card.critical::before { background: var(--critical); }
    .chart-card.amber::before { background: var(--high); }
    .chart-card.teal::before { background: var(--accent-teal); }
    .chart-card.multi::before { background: linear-gradient(90deg, var(--critical), var(--high), var(--medium-high), var(--low)); }
    .chart-card.full-width { grid-column: 1 / -1; }

    .card-header {
      margin-bottom: 16px;
    }

    .card-number {
      font-family: var(--font-mono);
      font-size: 9px;
      letter-spacing: 0.15em;
      text-transform: uppercase;
      color: var(--text-muted);
      margin-bottom: 4px;
    }

    .card-title {
      font-size: 13px;
      font-weight: 600;
      color: var(--text);
      line-height: 1.3;
    }

    .card-desc {
      font-size: 11px;
      color: var(--text-dim);
      margin-top: 3px;
    }

    canvas {
      display: block;
      width: 100% !important;
    }

    /* ── HEATMAP TABLE ── */
    .heatmap-wrap {
      overflow-x: auto;
    }

    .heatmap-table {
      width: 100%;
      border-collapse: collapse;
      font-size: 11px;
    }

    .heatmap-table th {
      font-family: var(--font-mono);
      font-size: 9px;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--text-muted);
      padding: 6px 10px;
      text-align: left;
      border-bottom: 1px solid var(--border);
      white-space: nowrap;
    }

    .heatmap-table th.center { text-align: center; }

    .heatmap-table td {
      padding: 7px 10px;
      border-bottom: 1px solid rgba(240,246,252,0.05);
      vertical-align: middle;
    }

    .heatmap-table tr:last-child td { border-bottom: none; }
    .heatmap-table tr:hover td { background: rgba(240,246,252,0.02); }

    .country-name {
      font-weight: 500;
      white-space: nowrap;
    }

    .stress-badge {
      display: inline-block;
      font-family: var(--font-mono);
      font-size: 9px;
      letter-spacing: 0.06em;
      padding: 2px 7px;
      border-radius: 2px;
      white-space: nowrap;
    }

    .badge-critical { color: var(--critical); background: var(--critical-dim); border: 1px solid rgba(218,54,51,0.3); }
    .badge-high { color: var(--high); background: var(--high-dim); border: 1px solid rgba(227,136,42,0.3); }
    .badge-medium-high { color: var(--medium-high); background: var(--medium-high-dim); border: 1px solid rgba(212,167,58,0.3); }
    .badge-medium { color: var(--medium); background: var(--medium-dim); border: 1px solid rgba(92,169,232,0.3); }
    .badge-low { color: var(--low); background: var(--low-dim); border: 1px solid rgba(63,185,80,0.3); }

    .cell-bar-wrap {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .cell-bar-track {
      flex: 1;
      height: 6px;
      background: var(--surface-3);
      border-radius: 3px;
      overflow: hidden;
      min-width: 60px;
    }

    .cell-bar-fill {
      height: 100%;
      border-radius: 3px;
    }

    .cell-value {
      font-family: var(--font-mono);
      font-size: 10px;
      color: var(--text-dim);
      white-space: nowrap;
      min-width: 38px;
      text-align: right;
    }

    .overdraft-flag {
      display: inline-block;
      font-family: var(--font-mono);
      font-size: 9px;
      color: var(--critical);
      background: var(--critical-dim);
      border: 1px solid rgba(218,54,51,0.3);
      padding: 1px 5px;
      border-radius: 2px;
      margin-left: 4px;
    }

    .precip-trend {
      display: flex;
      align-items: center;
      gap: 5px;
      font-family: var(--font-mono);
      font-size: 10px;
    }

    .trend-arrow {
      font-size: 12px;
      line-height: 1;
    }

    .trend-down { color: var(--critical); }
    .trend-up { color: var(--low); }
    .trend-neutral { color: var(--text-muted); }

    .td-center { text-align: center; }

    /* ── CONVERGENCE ALERT ── */
    .convergence-row td {
      background: rgba(218,54,51,0.05) !important;
    }

    /* ── FOOTER ── */
    .footnote {
      margin-top: 24px;
      padding-top: 16px;
      border-top: 1px solid var(--border);
      font-size: 10px;
      color: var(--text-muted);
      display: flex;
      gap: 24px;
      flex-wrap: wrap;
    }

    .footnote strong {
      font-family: var(--font-mono);
      color: var(--text-dim);
    }

    @keyframes fadeUp {
      from { opacity: 0; transform: translateY(12px); }
      to { opacity: 1; transform: translateY(0); }
    }

    .chart-card {
      animation: fadeUp 0.4s ease both;
    }
    .chart-card:nth-child(1) { animation-delay: 0.05s; }
    .chart-card:nth-child(2) { animation-delay: 0.10s; }
    .chart-card:nth-child(3) { animation-delay: 0.15s; }
    .chart-card:nth-child(4) { animation-delay: 0.20s; }
    .chart-card:nth-child(5) { animation-delay: 0.25s; }

    @media (prefers-reduced-motion: reduce) {
      .chart-card { animation: none; }
    }

    @media (max-width: 900px) {
      .main-grid { grid-template-columns: 1fr; }
      .chart-card.full-width { grid-column: auto; }
    }
  </style>
</head>
<body>
  <div class="page">

    <!-- HEADER -->
    <header>
      <div class="header-top">
        <div>
          <div class="label-tag">Water Security Analysis · 2023</div>
          <h1>Global Water Stress: Multi-Indicator Country Comparison</h1>
          <p class="subtitle">10-country composite assessment across supply-demand, groundwater overdraft, per-capita availability, and precipitation trends</p>
        </div>
        <div class="meta-pills">
          <span class="meta-pill">n = 10 countries</span>
          <span class="meta-pill">4 indicators</span>
          <span class="meta-pill">1990–2023</span>
        </div>
      </div>
    </header>

    <!-- LEGEND -->
    <div class="legend-strip">
      <span class="legend-title">Stress Class</span>
      <div class="legend-item"><span class="legend-dot" style="background:var(--critical)"></span>Extremely High</div>
      <div class="legend-item"><span class="legend-dot" style="background:var(--high)"></span>High</div>
      <div class="legend-item"><span class="legend-dot" style="background:var(--medium-high)"></span>Medium-High</div>
      <div class="legend-item"><span class="legend-dot" style="background:var(--medium)"></span>Medium</div>
      <div class="legend-item"><span class="legend-dot" style="background:var(--low)"></span>Low</div>
      <div class="legend-item" style="margin-left:auto;gap:8px;">
        <span style="font-family:var(--font-mono);font-size:10px;color:var(--text-muted)">Threshold:</span>
        <span style="font-family:var(--font-mono);font-size:10px;color:var(--text-dim)">Ratio &lt; 1.0 = demand exceeds supply &nbsp;|&nbsp; Extraction/Recharge &gt; 1.0 = overdraft &nbsp;|&nbsp; &lt; 1,000 m³/cap = scarcity</span>
      </div>
    </div>

    <!-- MAIN GRID -->
    <div class="main-grid">

      <!-- CHART 1: Supply-Demand Ratio -->
      <div class="chart-card critical">
        <div class="card-header">
          <div class="card-number">01 · Supply-Demand</div>
          <div class="card-title">Water Supply-to-Demand Ratio by Country</div>
          <div class="card-desc">Values below 1.0 indicate demand exceeds renewable supply — a critical deficit threshold</div>
        </div>
        <canvas id="chart-supply" height="260"></canvas>
      </div>

      <!-- CHART 2: Per Capita Freshwater (log scale) -->
      <div class="chart-card teal">
        <div class="card-header">
          <div class="card-number">02 · Per-Capita Availability</div>
          <div class="card-title">Annual Freshwater per Capita (log scale)</div>
          <div class="card-desc">Orders-of-magnitude disparity between water-rich and water-scarce nations; 1,000 m³ scarcity threshold shown</div>
        </div>
        <canvas id="chart-percapita" height="260"></canvas>
      </div>

      <!-- CHART 3: Groundwater Extraction vs Recharge -->
      <div class="chart-card amber">
        <div class="card-header">
          <div class="card-number">03 · Groundwater</div>
          <div class="card-title">Extraction vs. Natural Recharge Rate (km³/yr)</div>
          <div class="card-desc">Bars exceeding recharge indicate unsustainable overdraft of aquifers</div>
        </div>
        <canvas id="chart-groundwater" height="260"></canvas>
      </div>

      <!-- CHART 4: Precipitation Trends -->
      <div class="chart-card multi">
        <div class="card-header">
          <div class="card-number">04 · Precipitation Trend</div>
          <div class="card-title">Decadal Mean Precipitation 1990s → 2010s (mm/yr)</div>
          <div class="card-desc">Declining rainfall compounds water stress in already deficit regions; arrows show trend direction</div>
        </div>
        <canvas id="chart-precip" height="260"></canvas>
      </div>

      <!-- CHART 5: Full-width convergence heatmap table -->
      <div class="chart-card full-width multi">
        <div class="card-header">
          <div class="card-number">05 · Convergence Matrix</div>
          <div class="card-title">Multi-Indicator Water Crisis Severity — All Countries Ranked</div>
          <div class="card-desc">Countries ranked by supply-demand ratio (ascending). Highlighted rows indicate convergence of multiple severe stressors.</div>
        </div>
        <div class="heatmap-wrap">
          <table class="heatmap-table">
            <thead>
              <tr>
                <th>Country</th>
                <th>Stress Class</th>
                <th class="center" colspan="2">Supply / Demand Ratio</th>
                <th class="center" colspan="2">Per Capita Freshwater (m³/yr)</th>
                <th class="center" colspan="2">GW Extraction / Recharge</th>
                <th class="center">Precip Trend (1990s→2010s)</th>
              </tr>
            </thead>
            <tbody id="heatmap-body"></tbody>
          </table>
        </div>
      </div>

    </div><!-- /main-grid -->

    <div class="footnote">
      <div><strong>Sources:</strong> FAO AQUASTAT; WRI Aqueduct (2023 estimates). Groundwater recharge carries ±15% uncertainty in arid regions.</div>
      <div><strong>Note:</strong> Precipitation values are country-wide spatial averages; sub-national variability not reflected.</div>
    </div>

  </div><!-- /page -->

  <script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.3/dist/chart.umd.min.js"></script>
  <script>
    // ── DATA ──────────────────────────────────────────────────────────────────
    const countries = ['Saudi Arabia','Egypt','Pakistan','India','South Africa','Mexico','Australia','United States','Brazil','Canada'];

    const supplyDemand = [0.31, 0.48, 0.65, 0.72, 0.91, 1.08, 1.55, 1.82, 4.35, 6.12];

    const stressClass = {
      'Saudi Arabia': 'Extremely High',
      'Egypt': 'Extremely High',
      'Pakistan': 'Extremely High',
      'India': 'Extremely High',
      'South Africa': 'High',
      'Mexico': 'High',
      'Australia': 'Medium-High',
      'United States': 'Medium',
      'Brazil': 'Low',
      'Canada': 'Low',
    };

    const perCapita = {
      'India': 1486, 'Pakistan': 934, 'Egypt': 570, 'Saudi Arabia': 84,
      'Mexico': 3656, 'South Africa': 830, 'Australia': 20180,
      'United States': 8844, 'Brazil': 27436, 'Canada': 80620
    };

    const groundwater = {
      'India':        { ex: 251,  re: 432,  ratio: 0.58 },
      'Pakistan':     { ex: 64,   re: 55,   ratio: 1.16 },
      'Egypt':        { ex: 7.5,  re: 4.6,  ratio: 1.63 },
      'Saudi Arabia': { ex: 21.5, re: 3.8,  ratio: 5.66 },
      'Mexico':       { ex: 36,   re: 48,   ratio: 0.75 },
      'South Africa': { ex: 4.8,  re: 4.9,  ratio: 0.98 },
      'Australia':    { ex: 5.1,  re: 22,   ratio: 0.23 },
      'United States':{ ex: 112,  re: 128,  ratio: 0.88 },
      'Brazil':       { ex: 22,   re: 216,  ratio: 0.10 },
      'Canada':       { ex: 3.2,  re: 68,   ratio: 0.05 },
    };

    const precipTrends = {
      'India':         { '1990s': 1120, '2000s': 1095, '2010s': 1078 },
      'Pakistan':      { '1990s': 396,  '2000s': 378,  '2010s': 355  },
      'Egypt':         { '1990s': 52,   '2000s': 47,   '2010s': 41   },
      'Saudi Arabia':  { '1990s': 98,   '2000s': 89,   '2010s': 78   },
      'Mexico':        { '1990s': 758,  '2000s': 742,  '2010s': 725  },
      'South Africa':  { '1990s': 498,  '2000s': 475,  '2010s': 452  },
      'Australia':     { '1990s': 465,  '2000s': 490,  '2010s': 478  },
      'United States': { '1990s': 767,  '2000s': 780,  '2010s': 798  },
      'Brazil':        { '1990s': 1761, '2000s': 1748, '2010s': 1720 },
      'Canada':        { '1990s': 537,  '2000s': 548,  '2010s': 562  },
    };

    // ── COLOR HELPERS ────────────────────────────────────────────────────────
    const stressColors = {
      'Extremely High': '#da3633',
      'High': '#e3882a',
      'Medium-High': '#d4a73a',
      'Medium': '#5ca9e8',
      'Low': '#3fb950',
    };

    function colorForCountry(c) { return stressColors[stressClass[c]] || '#8b949e'; }
    function alphaColor(hex, a) {
      const r = parseInt(hex.slice(1,3),16);
      const g = parseInt(hex.slice(3,5),16);
      const b = parseInt(hex.slice(5,7),16);
      return `rgba(${r},${g},${b},${a})`;
    }

    const chartDefaults = {
      font: { family: "'IBM Plex Sans', sans-serif", size: 11 },
      color: '#8b949e',
    };
    Chart.defaults.font = chartDefaults.font;
    Chart.defaults.color = chartDefaults.color;

    const gridColor = 'rgba(240,246,252,0.07)';
    const borderColor = 'rgba(240,246,252,0.12)';

    // ── CHART 1: SUPPLY-DEMAND HORIZONTAL BAR ───────────────────────────────
    new Chart(document.getElementById('chart-supply'), {
      type: 'bar',
      data: {
        labels: countries,
        datasets: [{
          data: supplyDemand,
          backgroundColor: countries.map(c => alphaColor(colorForCountry(c), 0.75)),
          borderColor: countries.map(c => colorForCountry(c)),
          borderWidth: 1,
          borderRadius: 3,
          borderSkipped: false,
        }]
      },
      options: {
        indexAxis: 'y',
        responsive: true,
        plugins: {
          legend: { display: false },
          tooltip: {
            callbacks: {
              label: ctx => ` ${ctx.parsed.x.toFixed(2)} · ${stressClass[ctx.label]}`
            }
          },
          annotation: {}
        },
        scales: {
          x: {
            title: { display: true, text: 'Supply / Demand Ratio', color: '#6e7681', font: { size: 10 } },
            grid: { color: gridColor },
            border: { color: borderColor },
            ticks: { color: '#8b949e', font: { size: 10 } },
            min: 0,
          },
          y: {
            grid: { display: false },
            border: { color: borderColor },
            ticks: { color: c => {
              const label = countries[c.index];
              return colorForCountry(label);
            }, font: { size: 11, weight: '500' } }
          }
        }
      },
      plugins: [{
        id: 'threshold-line',
        afterDraw(chart) {
          const { ctx, scales: { x, y } } = chart;
          const xPos = x.getPixelForValue(1.0);
          ctx.save();
          ctx.beginPath();
          ctx.setLineDash([4, 3]);
          ctx.strokeStyle = 'rgba(255,255,255,0.35)';
          ctx.lineWidth = 1.5;
          ctx.moveTo(xPos, y.top);
          ctx.lineTo(xPos, y.bottom);
          ctx.stroke();
          ctx.setLineDash([]);
          ctx.fillStyle = 'rgba(255,255,255,0.5)';
          ctx.font = '9px IBM Plex Mono';
          ctx.fillText('1.0 threshold', xPos + 4, y.top + 10);
          ctx.restore();
        }
      }]
    });

    // ── CHART 2: PER-CAPITA LOG SCALE ───────────────────────────────────────
    const pcLabels = [...countries].sort((a,b) => perCapita[a] - perCapita[b]);
    const pcValues = pcLabels.map(c => perCapita[c]);

    new Chart(document.getElementById('chart-percapita'), {
      type: 'bar',
      data: {
        labels: pcLabels,
        datasets: [{
          data: pcValues,
          backgroundColor: pcLabels.map(c => alphaColor(colorForCountry(c), 0.75)),
          borderColor: pcLabels.map(c => colorForCountry(c)),
          borderWidth: 1,
          borderRadius: 3,
          borderSkipped: false,
        }]
      },
      options: {
        indexAxis: 'y',
        responsive: true,
        plugins: {
          legend: { display: false },
          tooltip: {
            callbacks: {
              label: ctx => ` ${ctx.parsed.x.toLocaleString()} m³/person/yr`
            }
          }
        },
        scales: {
          x: {
            type: 'logarithmic',
            title: { display: true, text: 'Freshwater per Capita (m³/yr, log scale)', color: '#6e7681', font: { size: 10 } },
            grid: { color: gridColor },
            border: { color: borderColor },
            ticks: {
              color: '#8b949e',
              font: { size: 10 },
              callback: v => v >= 1000 ? (v/1000)+'k' : v
            },
            min: 50,
          },
          y: {
            grid: { display: false },
            border: { color: borderColor },
            ticks: { color: c => colorForCountry(pcLabels[c.index]), font: { size: 11, weight: '500' } }
          }
        }
      },
      plugins: [{
        id: 'scarcity-line',
        afterDraw(chart) {
          const { ctx, scales: { x, y } } = chart;
          const xPos = x.getPixelForValue(1000);
          ctx.save();
          ctx.beginPath();
          ctx.setLineDash([4, 3]);
          ctx.strokeStyle = 'rgba(255,255,255,0.35)';
          ctx.lineWidth = 1.5;
          ctx.moveTo(xPos, y.top);
          ctx.lineTo(xPos, y.bottom);
          ctx.stroke();
          ctx.setLineDash([]);
          ctx.fillStyle = 'rgba(255,255,255,0.5)';
          ctx.font = '9px IBM Plex Mono';
          ctx.fillText('1,000 m³ scarcity', xPos + 4, y.top + 10);
          ctx.restore();
        }
      }]
    });

    // ── CHART 3: GROUNDWATER GROUPED BAR ────────────────────────────────────
    const gwCountries = [...countries].sort((a,b) => groundwater[b].ratio - groundwater[a].ratio);

    new Chart(document.getElementById('chart-groundwater'), {
      type: 'bar',
      data: {
        labels: gwCountries,
        datasets: [
          {
            label: 'Extraction (km³/yr)',
            data: gwCountries.map(c => groundwater[c].ex),
            backgroundColor: gwCountries.map(c => {
              return groundwater[c].ratio > 1.0
                ? alphaColor('#da3633', 0.80)
                : alphaColor('#5ca9e8', 0.55);
            }),
            borderColor: gwCountries.map(c => groundwater[c].ratio > 1.0 ? '#da3633' : '#5ca9e8'),
            borderWidth: 1,
            borderRadius: 2,
          },
          {
            label: 'Recharge (km³/yr)',
            data: gwCountries.map(c => groundwater[c].re),
            backgroundColor: 'rgba(63,185,80,0.25)',
            borderColor: '#3fb950',
            borderWidth: 1,
            borderRadius: 2,
            borderDash: [4,2],
          }
        ]
      },
      options: {
        indexAxis: 'y',
        responsive: true,
        plugins: {
          legend: {
            display: true,
            position: 'top',
            labels: { color: '#8b949e', font: { size: 10 }, boxWidth: 12 }
          },
          tooltip: {
            callbacks: {
              afterBody: items => {
                if (!items.length) return;
                const c = items[0].label;
                const r = groundwater[c].ratio;
                return r > 1.0
                  ? [`⚠ OVERDRAFT: extraction/recharge = ${r.toFixed(2)}`]
                  : [`Ratio: ${r.toFixed(2)} (sustainable)`];
              }
            }
          }
        },
        scales: {
          x: {
            title: { display: true, text: 'Volume (km³/year)', color: '#6e7681', font: { size: 10 } },
            grid: { color: gridColor },
            border: { color: borderColor },
            ticks: { color: '#8b949e', font: { size: 10 } }
          },
          y: {
            grid: { display: false },
            border: { color: borderColor },
            ticks: {
              color: c => {
                const label = gwCountries[c.index];
                return groundwater[label].ratio > 1.0 ? '#da3633' : colorForCountry(label);
              },
              font: { size: 11, weight: '500' }
            }
          }
        }
      }
    });

    // ── CHART 4: PRECIPITATION TREND LINES ──────────────────────────────────
    const precipOrder = [...countries].sort((a,b) =>
      (precipTrends[a]['2010s'] - precipTrends[a]['1990s']) - (precipTrends[b]['2010s'] - precipTrends[b]['1990s'])
    );

    const decades = ['1990s', '2000s', '2010s'];

    const precipDatasets = precipOrder.map(c => {
      const delta = precipTrends[c]['2010s'] - precipTrends[c]['1990s'];
      const col = delta < -10 ? '#da3633' : delta > 10 ? '#3fb950' : '#d4a73a';
      return {
        label: c,
        data: decades.map(d => precipTrends[c][d]),
        borderColor: col,
        backgroundColor: alphaColor(col, 0.06),
        borderWidth: delta < -10 ? 2.5 : 1.5,
        pointRadius: 3,
        pointHoverRadius: 5,
        tension: 0.3,
        fill: false,
      };
    });

    new Chart(document.getElementById('chart-precip'), {
      type: 'line',
      data: {
        labels: decades,
        datasets: precipDatasets,
      },
      options: {
        responsive: true,
        interaction: { mode: 'index' },
        plugins: {
          legend: {
            display: true,
