          </div>
        </td>
        <td colspan="2">
          <div class="cell-bar-wrap">
            <div class="cell-bar-track">
              <div class="cell-bar-fill" style="width:${Math.min(pc/pcMax*100,100)}%;background:${pcColor}"></div>
            </div>
